import{_ as a,o as n,a as p,b as l}from"./app.BAU4IqPF.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"数据结构(TensorAPI，试验特性)","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/data_structure_TensorAPI"},{"text":"Tensor数据结构","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/tensor_structure"},{"text":"MakeMemPtr","link":"/api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/MakeMemPtr"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/MakeMemPtr.md","filePath":"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/MakeMemPtr.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),t={name:"api/SIMD-API/basic_api/data_structure_TensorAPI/tensor_structure/MakeMemPtr.md"};function c(e,s,r,i,d,o){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>MakeMemPtr</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本接口为试验接口，在后续版本中可能会调整或改进，不保证后续兼容性。请开发者在使用过程中关注后续版本更新。</p></div><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>需要包含的头文件为：#include &quot;tensor_api/tensor.h&quot;。</p><p>MakeMemPtr用于构造带物理存储位置标记和数据类型信息的内存指针适配器HardwareMemPtr，支持的物理位置如下表所示。</p><p>MakeMemPtr提供三种调用形式：</p><ol><li>指定物理位置和数据类型，根据原始地址构造指针。</li><li>指定物理位置，从已有迭代器或指针适配器构造新指针。</li><li>从已有迭代器或指针适配器中自动推导物理位置。</li></ol><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>指定物理位置和数据类型，根据原始地址构造：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Hardware</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DataType</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Addr</span><span class="p">,</span><span class="w"> </span><span class="n">EnableMakePtrByTrait</span><span class="o">&lt;</span><span class="n">Hardware</span><span class="p">,</span><span class="w"> </span><span class="n">Addr</span><span class="o">&gt;</span><span class="w"> </span><span class="n">Enable</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="p">(</span><span class="n">Addr</span><span class="w"> </span><span class="n">addr</span><span class="p">)</span>
</code></pre></div></li><li><p>指定物理位置，从已有迭代器构造：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Hardware</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">Iterator</span><span class="p">,</span><span class="w"> </span><span class="n">EnableMakeHardwarePtr</span><span class="o">&lt;</span><span class="n">Hardware</span><span class="p">,</span><span class="w"> </span><span class="n">Iterator</span><span class="o">&gt;</span><span class="w"> </span><span class="n">Enable</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="p">(</span><span class="n">Iterator</span><span class="w"> </span><span class="n">iterator</span><span class="p">)</span>
</code></pre></div></li><li><p>从已有迭代器中自动推导物理位置：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Iterator</span><span class="p">,</span><span class="w"> </span><span class="n">EnableMakePtrByIter</span><span class="o">&lt;</span><span class="n">Iterator</span><span class="o">&gt;</span><span class="w"> </span><span class="n">Enable</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="p">(</span><span class="n">Iterator</span><span class="w"> </span><span class="n">iterator</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 支持的物理位置</p><table><thead><tr><th align="left">Location</th><th align="left">说明</th><th align="left">用途</th></tr></thead><tbody><tr><td align="left">Location::GM</td><td align="left">Global Memory</td><td align="left">全局内存，张量输入输出的主要存储区域</td></tr><tr><td align="left">Location::L1</td><td align="left">L1 Buffer</td><td align="left">一级缓存，矩阵搬运和计算前的数据暂存区</td></tr><tr><td align="left">Location::L0A</td><td align="left">L0A Buffer</td><td align="left">矩阵计算左输入缓存</td></tr><tr><td align="left">Location::L0B</td><td align="left">L0B Buffer</td><td align="left">矩阵计算右输入缓存</td></tr><tr><td align="left">Location::L0ScaleA</td><td align="left">L0 ScaleA Buffer</td><td align="left">MX矩阵计算ScaleA缓存</td></tr><tr><td align="left">Location::L0ScaleB</td><td align="left">L0 ScaleB Buffer</td><td align="left">MX矩阵计算ScaleB缓存</td></tr><tr><td align="left">Location::L0C</td><td align="left">L0C Buffer</td><td align="left">矩阵计算结果缓存</td></tr><tr><td align="left">Location::UB</td><td align="left">UB</td><td align="left">统一缓存，矢量计算的数据存储区</td></tr><tr><td align="left">Location::BIAS</td><td align="left">BiasTable Buffer</td><td align="left">偏置表缓存，带偏置矩阵计算的偏置存放区</td></tr><tr><td align="left">Location::FIXBUF</td><td align="left">Fixpipe Buffer</td><td align="left">Fixpipe输出缓存，L0C到GM/UB的中转区</td></tr></tbody></table><p><strong>表2</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">类型</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">Hardware</td><td align="center">输入</td><td align="left">物理存储位置类型。</td></tr><tr><td align="left">DataType</td><td align="center">输入</td><td align="left">数据类型。</td></tr><tr><td align="left">Addr</td><td align="center">输入</td><td align="left">偏移量数值的类型。</td></tr><tr><td align="left">Iterator</td><td align="center">输入</td><td align="left">迭代器类型或已有指针适配器类型。</td></tr></tbody></table><p><strong>表3</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="center">类型</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">addr</td><td align="center">输入</td><td align="left">地址偏移量，即相对于基地址的偏移大小。</td></tr><tr><td align="left">iterator</td><td align="center">输入</td><td align="left">已有的硬件地址迭代器或指针适配器对象。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回HardwareMemPtr&lt;PtrPattern, Pointer&gt;类型的指针适配器对象，其中：</p><ul><li>PtrPattern表示指定或推导得到的物理位置；</li><li>Pointer表示对应地址空间下的指针类型，例如__gm__ float*、__cbuf__ half*等。</li></ul><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>指定Hardware时，必须是受支持的物理位置类型。</li><li>Iterator需要满足对应构造路径的模板约束。</li><li>自动推导形式要求输入对象本身已经带有可识别的硬件位置信息。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">AscendC</span><span class="o">::</span><span class="nn">Te</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">gmOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">l1Offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">l0aOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">ubOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span>
<span class="c1">// 1. 从原始地址构造：指定物理位置和数据类型</span>
<span class="k">auto</span><span class="w"> </span><span class="n">gmPtr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="o">&lt;</span><span class="n">Location</span><span class="o">::</span><span class="n">GM</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">gmOffset</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1Ptr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="o">&lt;</span><span class="n">Location</span><span class="o">::</span><span class="n">L1</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">&gt;</span><span class="p">(</span><span class="n">l1Offset</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l0aPtr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="o">&lt;</span><span class="n">Location</span><span class="o">::</span><span class="n">L0A</span><span class="p">,</span><span class="w"> </span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="n">l0aOffset</span><span class="p">);</span>
<span class="k">auto</span><span class="w"> </span><span class="n">ubPtr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="o">&lt;</span><span class="n">Location</span><span class="o">::</span><span class="n">UB</span><span class="p">,</span><span class="w"> </span><span class="n">bfloat16_t</span><span class="o">&gt;</span><span class="p">(</span><span class="n">ubOffset</span><span class="p">);</span>

<span class="c1">// 2. 配合MakeTensor构造张量</span>
<span class="k">auto</span><span class="w"> </span><span class="n">gmA</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">gmPtr</span><span class="p">,</span><span class="w"> </span><span class="n">MakeFrameLayout</span><span class="o">&lt;</span><span class="n">NDExtLayoutPtn</span><span class="p">,</span><span class="w"> </span><span class="n">LayoutTraitDefault</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1A</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeTensor</span><span class="p">(</span><span class="n">l1Ptr</span><span class="p">,</span><span class="w"> </span><span class="n">MakeFrameLayout</span><span class="o">&lt;</span><span class="n">NZLayoutPtn</span><span class="p">,</span><span class="w"> </span><span class="n">LayoutTraitDefault</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">n</span><span class="p">));</span>

<span class="c1">// 3. 从已有指针适配器继承位置（自动推导）</span>
<span class="k">auto</span><span class="w"> </span><span class="n">anotherPtr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="p">(</span><span class="n">gmPtr</span><span class="p">);</span>

<span class="c1">// 4. 从已有迭代器指定新位置</span>
<span class="k">auto</span><span class="w"> </span><span class="n">l1FromIter</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MakeMemPtr</span><span class="o">&lt;</span><span class="n">Location</span><span class="o">::</span><span class="n">L1</span><span class="o">&gt;</span><span class="p">(</span><span class="n">someIterator</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const f=a(t,[["render",c]]);export{g as __pageData,f as default};
